INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das agile Vorgehensmodell nur für Softwareentwicklung geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in anderen Bereichen anwendbar"}, {"text": "Ja", "correct": false, "because": "Nicht auf IT beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem agilen Ansatz?', 3, '[{"text": "Flexibilität und Anpassung", "correct": true, "because": "Reagiert auf Änderungen"}, {"text": "Feste Planung", "correct": false, "because": "Gegenteil von agil"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien gehören zum agilen Vorgehensmodell?', 5, '[{"text": "Iterative Entwicklung", "correct": true, "because": "Schrittweise Fortschritte"}, {"text": "Kundenzentrierung", "correct": true, "because": "Fokus auf Bedürfnisse"}, {"text": "Langfristige Planung", "correct": false, "because": "Kurzfristige Zyklen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Agile Projekte nutzen Sprints. b) Sie erfordern feste Anforderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anforderungen flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der agilen Methode?', 4, '[{"text": "Kundenfeedback", "correct": false, "because": "Kern der Anpassung"}, {"text": "Teamkommunikation", "correct": false, "because": "Essenziell für Erfolg"}, {"text": "Feste Deadlines", "correct": true, "because": "Flexibilität im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Agile immer Scrum bedeutet?', 2, '[{"text": "Nein", "correct": true, "because": "Scrum ist nur ein Framework"}, {"text": "Ja", "correct": false, "because": "Andere Methoden möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für kurze Entwicklungszyklen?', 3, '[{"text": "Sprints", "correct": true, "because": "Typisch agil"}, {"text": "Wasserfallmodell", "correct": false, "because": "Linear und langfristig"}, {"text": "Einmalige Planung", "correct": false, "because": "Nicht iterativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einem agilen Projekt?', 5, '[{"text": "Regelmäßige Reviews", "correct": true, "because": "Überprüft Fortschritt"}, {"text": "Selbstorganisierte Teams", "correct": true, "because": "Fördert Eigenverantwortung"}, {"text": "Detaillierte Vorabplanung", "correct": false, "because": "Weniger detailliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Agile fördert Zusammenarbeit. b) Es ist chaotisch. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Strukturiert, nicht chaotisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der agilen Methode unwichtig?', 4, '[{"text": "Iterationen", "correct": false, "because": "Kern des Prozesses"}, {"text": "Kundenbeteiligung", "correct": false, "because": "Entscheidend für Erfolg"}, {"text": "Langfristige Dokumentation", "correct": true, "because": "Fokus auf Arbeitsprodukt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind agile Teams hierarchisch?', 2, '[{"text": "Nein", "correct": true, "because": "Selbstorganisation im Fokus"}, {"text": "Ja", "correct": false, "because": "Flache Strukturen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt das agile Vorgehensmodell?', 4, '[{"text": "Schnelle Anpassung", "correct": true, "because": "Reagiert auf Änderungen"}, {"text": "Höhere Qualität", "correct": true, "because": "Regelmäßige Tests"}, {"text": "Feste Kosten", "correct": false, "because": "Kosten flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Agile keine Planung braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kurzfristige Planung nötig"}, {"text": "Ja", "correct": false, "because": "Planung anders strukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im agilen Ansatz?', 3, '[{"text": "Kundenwert", "correct": true, "because": "Fokus auf Nutzen"}, {"text": "Detaillierte Dokumentation", "correct": false, "because": "Sekundär"}, {"text": "Feste Zeitpläne", "correct": false, "because": "Flexibilität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Agile nutzt Feedback-Schleifen. b) Es ist für große Teams ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für große Teams skalierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das agile Vorgehensmodell?', 5, '[{"text": "Unklare Gesamtkosten", "correct": true, "because": "Flexibilität erschwert Planung"}, {"text": "Hohe Teamabhängigkeit", "correct": true, "because": "Kommunikation entscheidend"}, {"text": "Schnelle Fertigstellung", "correct": false, "because": "Iterativ, nicht fix"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Agile unwichtig?', 3, '[{"text": "Sprint-Reviews", "correct": false, "because": "Überprüft Fortschritt"}, {"text": "Teamautonomie", "correct": false, "because": "Fördert Effizienz"}, {"text": "Langfristige Meilensteine", "correct": true, "because": "Kurzfristiger Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert Agile die Kundeneinbindung?', 3, '[{"text": "Ja", "correct": true, "because": "Kunde regelmäßig beteiligt"}, {"text": "Nein", "correct": false, "because": "Kernprinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Agile feste Rollen vorschreibt?', 2, '[{"text": "Nein", "correct": true, "because": "Rollen flexibel, je nach Framework"}, {"text": "Ja", "correct": false, "because": "Abhängig von Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Framework wähle ich für agile Projekte?', 4, '[{"text": "Scrum", "correct": true, "because": "Populär und strukturiert"}, {"text": "Wasserfall", "correct": false, "because": "Nicht agil"}, {"text": "Einmalplanung", "correct": false, "because": "Statisch"}]');
